import sys, json, time, platform, math, random, statistics as stats
from pathlib import Path

START = time.time()
sys.path.append('storage/shared')

# Seeding utilities (package or shim)
seed_tools_ok = True
try:
    from utilities.seed_tools import set_seed, make_rng, seed_from_str, mix_seed
except Exception:
    seed_tools_ok = False
    try:
        from seed_tools import set_seed, make_rng, seed_from_str, mix_seed
    except Exception:
        import random as _r, hashlib as _h
        def _u32(x): return int(x) & 0xFFFFFFFF
        def set_seed(s): _r.seed(_u32(s)); return _u32(s)
        def make_rng(s): set_seed(s); return None, _r.Random(_u32(s))
        def seed_from_str(s): return int(_h.sha256(s.encode()).hexdigest()[:8], 16)
        def mix_seed(a,b): return (_u32(a) ^ (_u32(b) + 0x9E3779B9)) & 0xFFFFFFFF

from coord.lossy_ring import simulate_lossy_ring
from coord.bidirectional_ring import simulate_bidir_broadcast
from coord.baseline_ring import simulate_ring_broadcast
from coord.metrics import basic_metrics

base_seed = seed_from_str("Axiom-lossy-ring-v0")
set_seed(base_seed)
_, _ = make_rng(base_seed)

def expected_steps_uni(N: int) -> int:
    return max(0, N - 1)
def expected_steps_bidir(N: int) -> int:
    return math.ceil((N - 1) / 2)

cfg = {
    "N": 24,
    "max_steps": 400,
    "replicates": 20,
    "p_values": [1.0, 0.8],
    "reliabilities": [1.0, 0.95, 0.8],
    "modes": ["uni", "bidir"]
}

# Deterministic verification (r=1, p=1)
det_cases = {}
for mode in cfg["modes"]:
    if mode == "uni":
        det = simulate_ring_broadcast(N=cfg["N"], p_send=1.0, max_steps=cfg["max_steps"])
        det_steps = det["steps_to_full"]
        det_ok = (det_steps == expected_steps_uni(cfg["N"]))
    else:
        det = simulate_bidir_broadcast(N=cfg["N"], p_send=1.0, max_steps=cfg["max_steps"])
        det_steps = det["steps_to_full"]
        det_ok = (det_steps == expected_steps_bidir(cfg["N"]))
    det_cases[mode] = {"observed": det_steps, "ok": bool(det_ok)}

# Lossy experiments grid
results = []
for mode in cfg["modes"]:
    for p in cfg["p_values"]:
        for r in cfg["reliabilities"]:
            if p == 1.0 and r == 1.0:
                continue  # deterministic case already recorded
            run_metrics = []
            succ = 0
            deliveries_per_step = []
            for k in range(cfg["replicates"]):
                run_seed = mix_seed(base_seed, hash((mode, p, r, k)) & 0xFFFFFFFF)
                rng = random.Random(run_seed)
                res = simulate_lossy_ring(
                    N=cfg["N"],
                    p_send=p,
                    reliability=r,
                    bidirectional=(mode == "bidir"),
                    max_steps=cfg["max_steps"],
                    rng=rng,
                    track_history=True,
                )
                met = basic_metrics({
                    "N": res["N"],
                    "steps": res["steps"],
                    "final_informed": res["final_informed"],
                    "steps_to_full": res["steps_to_full"],
                    "messages_sent": res["messages_sent"],
                })
                run_metrics.append(met)
                if res["steps_to_full"] is not None:
                    succ += 1
                if res["steps"] > 0:
                    deliveries_per_step.append(res["deliveries"] / res["steps"])
            # Aggregate
            def _vals(key):
                v = [m.get(key) for m in run_metrics]
                return [x for x in v if x is not None]
            agg = {}
            for key in ["coverage", "time_to_full", "throughput_msgs_per_step"]:
                v = _vals(key)
                if v:
                    agg[key] = {
                        "count": len(v),
                        "mean": float(stats.fmean(v)),
                        "min": float(min(v)),
                        "max": float(max(v)),
                    }
                else:
                    agg[key] = {"count": 0}
            agg["success_rate"] = succ / cfg["replicates"]
            agg["deliveries_per_step_mean"] = float(stats.fmean(deliveries_per_step)) if deliveries_per_step else None
            results.append({
                "mode": mode,
                "p_send": p,
                "reliability": r,
                "replicates": cfg["replicates"],
                "aggregate": agg,
            })

out_dir = Path("storage/shared/coord/results")
out_dir.mkdir(parents=True, exist_ok=True)
out_path = out_dir / "axiom_lossy_ring_v0.json"

report = {
    "env": {
        "python": platform.python_version(),
        "implementation": platform.python_implementation(),
        "platform": platform.platform(),
        "seed_tools_imported": seed_tools_ok,
    },
    "config": cfg,
    "deterministic_checks": det_cases,
    "grid_results": results,
}

with open(out_path, "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2, sort_keys=True)

END = time.time()
# Compact summary emphasizing robustness trends
def pick(mode, p, r):
    for row in results:
        if row["mode"] == mode and row["p_send"] == p and row["reliability"] == r:
            return row["aggregate"]
    return {}
uni_r08 = pick("uni", 0.8, 0.8)
bi_r08 = pick("bidir", 0.8, 0.8)
print("=== Lossy Links Ring v0 ===")
print(json.dumps({
    "artifact": str(out_path),
    "deterministic_ok": det_cases,
    "example_uni_p0.8_r0.8": uni_r08,
    "example_bidir_p0.8_r0.8": bi_r08,
    "timing_sec": round(END - START, 6),
}, indent=2))
print("Lossy links baseline complete.")

